lemma poissonBracket_angularMomentumSq_eq_zero_of_hasGradientAt
    {H : EuclideanSpace ℝ (Fin 3) → EuclideanSpace ℝ (Fin 3) → ℝ}
    {p q : EuclideanSpace ℝ (Fin 3)} {a c : ℝ}
    (hp : HasGradientAt (fun p' => H p' q) (a • p) p)
    (hq : HasGradientAt (fun q' => H p q') (c • q) q) :
    poissonBracket angularMomentumSq H p q = 0

lemma poissonBracket_angularMomentumZ_eq_zero_of_hasGradientAt
    {H : EuclideanSpace ℝ (Fin 3) → EuclideanSpace ℝ (Fin 3) → ℝ}
    {p q : EuclideanSpace ℝ (Fin 3)} {a c : ℝ}
    (hp : HasGradientAt (fun p' => H p' q) (a • p) p)
    (hq : HasGradientAt (fun q' => H p q') (c • q) q) :
    poissonBracket angularMomentumZ H p q = 0

lemma integrabilityDomain_eq : integrabilityDomain =
    {x | (x.1 0 * x.2 0 + x.1 1 * x.2 1 + x.1 2 * x.2 2) *
      ((x.2 1 * x.1 2 - x.2 2 * x.1 1) ^ 2 + (x.2 2 * x.1 0 - x.2 0 * x.1 2) ^ 2) ≠ 0}

lemma coupled_spring_potential :
    let U := fun x : EuclideanSpace ℝ (Fin 2) => (x 0)^2 + x 0 * x 1 + (x 1)^2
    IsLocalMin U {
        ofLp := ![0,0]
    }

def HamiltonianSystem.IsLiouvilleIntegrableOn {d : ℕ}
    (S : HamiltonianSystem 𝓘(ℝ, EuclideanSpace ℝ (Fin d)) ⟨EuclideanSpace ℝ (Fin d)⟩)
    (U : Set (EuclideanSpace ℝ (Fin d) × EuclideanSpace ℝ (Fin d))) : Prop

lemma LiouvilleIntegrableOn.deriv_comp_eq_zero {d : ℕ}
    {U : Set (EuclideanSpace ℝ (Fin d) × EuclideanSpace ℝ (Fin d))}
    {H : EuclideanSpace ℝ (Fin d) → EuclideanSpace ℝ (Fin d) → ℝ}
    (LI : LiouvilleIntegrableOn U H)
    (p q : Time → EuclideanSpace ℝ (Fin d)) (t : Time) (i : Fin d)
    (heq : hamiltonEqOp (fun _ => H) p q = 0)
    (hp : DifferentiableAt ℝ p t) (hq : DifferentiableAt ℝ q t) (hU : (p t, q t) ∈ U) :
    ∂ₜ (fun t => LI.f i (p t) (q t)) t = 0

lemma IsSolution.deriv_eq_of_force_eq_zero_on {S : NewtonianSystem X} {r : Time → X}
    (hr : S.IsSolution r) {a b : Time} (hF : ∀ t ∈ Set.Icc a b, S.force (r t) = 0) :
    ∀ t ∈ Set.Icc a b, ∂ₜ r t = ∂ₜ r a

lemma lagrangianSystem_coord_eq (p : Parameters) (t₀ : Time) (t : ℝ) {q : ℂ}
    (v : ℂ) (hq : p.r₁ / 2 ≤ ‖q‖) :
    (lagrangianSystem p).coord t₀ (t, q, v) = ‖v‖ ^ 2 / 2 + p.mu / ‖q‖

lemma pack_deriv {f g : ℝ → ℝ} {f' g' t : ℝ}
    (hf : HasDerivAt f f' t) (hg : HasDerivAt g g' t) :
    HasDerivAt (fun s => pack (f s) (g s)) (pack f' g') t

lemma apsidal_parameters_unique (p : Parameters) {A E : ℝ}
    (_hA : 0 < A) (h₁ : A*(1-E)=p.r₁) (h₂ : A*(1+E)=p.r₂) :
    A = p.a ∧ E = p.e

lemma first_square_strict_of_h_ne (s : Shape) {w h : ℝ}
    (hf : s.Feasible w h) (hne : h ≠ s.hH) :
    s.burnH₁ ^ 2 < s.burnSquare₁ w h

lemma invariant_pair_of_first_square_eq (s : Shape) {w h : ℝ}
    (hf : s.Feasible w h) (heq : s.burnSquare₁ w h = s.burnH₁^2) :
    h = s.hH ∧ w = s.energyH

def endpoints (p : Units) (a : KeplerArc p.mu)
    (h₀ : (a.state a.t₀).radius=p.r₁) (h₁ : (a.state a.t₁).radius=p.r₂) :
    PhysicalEndpoints p
